{

"kind": "propose",
"summary": "Adjust probe timeouts to accommodate application startup time",
"hypotheses": [
    {
        "root_cause_class": "probe_timeout_too_short",
        "summary": "Readiness and liveness probes timeout before application is ready",
        "supporting": ["probe_timeouts", "ev-rollout_history"],
        "contradicting": ["killed_during_startup", "crashed_on_its_own"],
        "missing": ["container_logs_tail"],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "Need container logs to confirm application behavior during probe failures",
        "supporting": ["container_logs_tail"],
        "contradicting": [],
        "missing": [],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search-api", "uid": "uid-deployment-search-api"},
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        },
        "readiness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Reduce probe timeouts to 5 seconds, allowing application time to initialize before probe checks",
    "rationale": "Current liveness/readiness timeouts (1s) are too short for application startup. Evidence shows probe timeouts and restarts without application crashes. Increasing timeouts aligns with observed startup delays and prevents premature termination.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-target_events", "ev-pod_states"],
    "cited_predicates": ["probe_timeouts", "probe_kills", "killed_during_startup"]
}
}
